fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    debug_assert!(!v.is_empty());

    let mut lo: usize = 0;
    let mut hi: usize = v.len() - 1;

    while lo < hi {
        // mid is always in-bounds, and avoids overflow
        let mid = lo + (hi - lo) / 2;

        if v[mid] < k {
            // k must be in (mid, hi], so shrink from the left
            lo = mid + 1;
        } else {
            // k must be in [lo, mid], so shrink from the right
            hi = mid;
        }
    }

    // With the problem's guarantee that k occurs, this must hold.
    debug_assert!(v[lo] == k);
    lo
}